package com.minimarket.producto.controller; import org.springframework.security.access.prepost.PreAuthorize;
import com.minimarket.common.ApiResponse; import com.minimarket.producto.dto.*; import com.minimarket.producto.service.UnidadMedidaService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @PreAuthorize("hasAuthority('CATALOGO_ADMINISTRAR')") @RequestMapping("/api/unidades-medida") @RequiredArgsConstructor public class UnidadMedidaController{private final UnidadMedidaService s;@GetMapping public ApiResponse<Page<UnidadMedidaResponseDTO>> listar(Pageable p){return ApiResponse.ok(s.listar(p));}@GetMapping("/{id}")public ApiResponse<UnidadMedidaResponseDTO> obtener(@PathVariable Long id){return ApiResponse.ok(s.obtener(id));}@PostMapping @ResponseStatus(HttpStatus.CREATED)public ApiResponse<UnidadMedidaResponseDTO> crear(@Valid @RequestBody UnidadMedidaRequestDTO r){return ApiResponse.ok(s.crear(r));}@PutMapping("/{id}")public ApiResponse<UnidadMedidaResponseDTO> actualizar(@PathVariable Long id,@Valid @RequestBody UnidadMedidaRequestDTO r){return ApiResponse.ok(s.actualizar(id,r));}}